import {
  useWindowDimensions,
  Text,
  View,
  LayoutChangeEvent,
  Alert,
  TextInput
} from 'react-native'
import Animated, {
  type SharedValue,
  useAnimatedStyle,
  withSpring,
  interpolate
} from 'react-native-reanimated'
import { GestureDetector } from 'react-native-gesture-handler'
import { AnimatedImage, AnimatedTouchableOpacity } from '@/components'
import { HomeScreenProjectGroup } from '@/types'
import { formatDistanceToNow } from 'date-fns'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
// import { launchMetroServerApp, launchPreviewApp } from '@/utils/launchApp'
// import { AnythingLauncherReloadOverlayModule } from '@anythingai/launcher'
import * as Haptics from 'expo-haptics'
import { getBlurhashFromUUID } from '@/utils/getBlurhashFromUUID'
import { APPEAR_DURATION } from '@/constants'
import { useBoolVariation } from '@launchdarkly/react-native-client-sdk'
import { Edit, Trash2 } from 'lucide-react-native'
import { useProjectGroupSwipeGesture } from './useProjectGroupSwipeGesture'
import {
  useDeleteProjectGroupMutation,
  useRenameProjectGroupMutation
} from '@/generated/graphql'
import { toast } from '@/utils/toast'
import { useRef, useState, useLayoutEffect } from 'react'
import { useCurrentOrganization } from '@/utils/hooks'
import { getGlobalTapCoordinates } from '@/utils'
import { router } from 'expo-router'

export const PROJECT_GROUP_ITEM_BUTTON_ANIMATION_DURATION = 350

type ProjectGroupItemButtonProps = {
  item: HomeScreenProjectGroup
  index: number
  listYPosition: SharedValue<number>
  activeButtonId: SharedValue<string | null>
  resetTriggerId: SharedValue<string | null>
}

export const ProjectGroupItemButton = ({
  item,
  index,
  listYPosition,
  activeButtonId,
  resetTriggerId
}: ProjectGroupItemButtonProps) => {
  const { height } = useWindowDimensions()
  const { theme } = useTheme()
  // const withBundleProjectGroupRevision = useBoolVariation(
  // 	'bundle-project-group-revision',
  // 	false
  // )
  const projectGroupGestureEnabled = useBoolVariation(
    'project-group-gesture-enabled',
    true
  )
  const [renameProjectGroup] = useRenameProjectGroupMutation()
  const [deleteProjectGroup] = useDeleteProjectGroupMutation()
  const [projectGroupName, setProjectGroupName] = useState(item.name)
  const [editingProjectGroupName, setEditingProjectGroupName] = useState(false)
  const projectGroupNameInputRef = useRef<TextInput>(null)

  useLayoutEffect(() => {
    if (editingProjectGroupName) {
      projectGroupNameInputRef.current?.focus()
    }
  }, [editingProjectGroupName])

  const handleStartRenamingProjectGroupName = () => {
    resetToOriginalState()
    setEditingProjectGroupName(true)
  }

  const handleDeleteButtonPressed = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy)
    Alert.alert('Delete Item?', 'Are you sure you want to delete this item?', [
      {
        text: 'Cancel',
        style: 'cancel',
        onPress: () => {
          resetToOriginalState()
        }
      },
      {
        text: 'Delete',
        style: 'destructive',
        onPress: handleDeleteProjectGroup
      }
    ])
  }

  const handleRenameProjectGroup = async (name: string) => {
    try {
      const { data } = await renameProjectGroup({
        variables: {
          input: {
            id: item.id,
            name
          }
        },
        optimisticResponse: {
          __typename: 'Mutation',
          renameProjectGroup: {
            __typename: 'RenameProjectGroupPayload',
            success: true,
            projectGroup: {
              __typename: 'ProjectGroup',
              name,
              id: item.id
            }
          }
        }
      })
      if (!data?.renameProjectGroup?.success) {
        console.log('Failed to rename project group')
      }
    } catch (error) {
      console.log('Error renaming project group:', error)
      toast.show({
        variant: 'error',
        message: 'Error renaming project group'
      })
    }
  }

  const handleDeleteProjectGroup = async () => {
    resetToOriginalState()
    try {
      const { data } = await deleteProjectGroup({
        variables: {
          input: {
            id: item.id
          }
        },
        update: (cache) => {
          cache.evict({ id: `ProjectGroup:${item.id}` })
          cache.gc()
        },
        optimisticResponse: {
          __typename: 'Mutation',
          deleteProjectGroup: {
            __typename: 'DeleteProjectGroupPayload',
            success: true
          }
        }
      })
      if (!data?.deleteProjectGroup?.success) {
        console.log('Failed to delete project group')
      }
    } catch (error) {
      console.log('Error deleting project group:', error)
      toast.show({
        variant: 'error',
        message: 'Error deleting project group'
      })
    }
  }

  const {
    panGesture,
    translateX,
    editButtonScale,
    deleteButtonScale,
    deleteButtonWidth,
    handleButtonLayout: handleSwipeButtonLayout,
    resetToOriginalState
  } = useProjectGroupSwipeGesture({
    buttonId: item.id,
    activeButtonId,
    resetTriggerId,
    enabled: !editingProjectGroupName,
    onDelete: handleDeleteButtonPressed,
    onButtonLayout: () => { }
  })

  const handleButtonLayout = (event: LayoutChangeEvent) => {
    const width = event.nativeEvent.layout.width
    handleSwipeButtonLayout(width)
  }

  const { currentOrganization } = useCurrentOrganization()

  const handleProjectGroupPress = (item: HomeScreenProjectGroup) => {
    const { ax, ay } = getGlobalTapCoordinates()
    router.push({
      pathname: '/new-project',
      params: {
        ax,
        ay,
        projectGroupId: item.id,
        organizationId: item.organizationId,
        canUseMAX: String(currentOrganization?.canUseMax ?? false)
      }
    })
  }

  const entranceAnimationStyle = useAnimatedStyle(() => ({
    transform: [
      {
        translateX: withSpring(
          interpolate(listYPosition.get(), [height, 0], [index * 40, 0]),
          {
            duration: APPEAR_DURATION,
            dampingRatio: 1
          }
        )
      },
      {
        translateY: withSpring(
          interpolate(listYPosition.get(), [height, 0], [(index + 1) * 20, 0]),
          {
            duration: APPEAR_DURATION,
            dampingRatio: 1
          }
        )
      }
    ]
  }))

  const swipeAnimationStyle = useAnimatedStyle(() => ({
    transform: [{ translateX: translateX.value }]
  }))

  const editButtonAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: editButtonScale.value }]
  }))

  const deleteButtonAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: deleteButtonScale.value }],
    width: deleteButtonWidth.value,
    borderRadius: deleteButtonWidth.value / 2
  }))

  const appImage = item.latestRevision?.expoSettings?.appIconUrl
    ? { uri: item.latestRevision?.expoSettings?.appIconUrl }
    : { blurhash: getBlurhashFromUUID(item.id) }

  const buttonContent = (
    <AnimatedTouchableOpacity
      activeOpacity={1}
      style={[
        styles.projectGroupButton(theme),
        entranceAnimationStyle,
        swipeAnimationStyle
      ]}
      onLayout={handleButtonLayout}
      onPress={() => {
        Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
        handleProjectGroupPress(item)
      }}
    >
      <AnimatedImage
        source={appImage}
        style={styles.projectGroupItemImageContainer}
      />
      <Animated.View style={styles.projectGroupItemLabelsContainer}>
        <Animated.View style={styles.projectGroupItemDetails}>
          <TextInput
            ref={projectGroupNameInputRef}
            style={styles.projectGroupItemName(theme)}
            numberOfLines={1}
            value={projectGroupName}
            onChangeText={setProjectGroupName}
            pointerEvents={editingProjectGroupName ? 'auto' : 'none'}
            onBlur={async () => {
              await handleRenameProjectGroup(projectGroupName)
              setEditingProjectGroupName(false)
            }}
            returnKeyType="done"
          />
        </Animated.View>
        {!!item.updatedAt && (
          <Animated.View>
            <Text style={styles.projectGroupItemLastEdited(theme)}>
              {formatDistanceToNow(new Date(item.updatedAt))}
            </Text>
          </Animated.View>
        )}
      </Animated.View>
    </AnimatedTouchableOpacity>
  )

  return (
    <>
      <View style={styles.actionButtonsContainer}>
        <AnimatedTouchableOpacity
          style={[
            styles.actionButton,
            editButtonAnimatedStyle,
            { backgroundColor: colors[theme].gray[50] }
          ]}
          onPress={() => {
            Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy)
            handleStartRenamingProjectGroupName()
          }}
        >
          <Edit size={18} color={colors[theme].gray[900]} />
        </AnimatedTouchableOpacity>
        <AnimatedTouchableOpacity
          style={[
            styles.actionButton,
            deleteButtonAnimatedStyle,
            { backgroundColor: colors.light.red[500] }
          ]}
          onPress={handleDeleteButtonPressed}
        >
          <Trash2 size={18} color={colors.light.gray[25]} />
        </AnimatedTouchableOpacity>
      </View>
      {projectGroupGestureEnabled ? (
        <GestureDetector gesture={panGesture}>{buttonContent}</GestureDetector>
      ) : (
        buttonContent
      )}
    </>
  )
}

const styles = defineStyles({
  projectGroupItemContainer: {
    flexDirection: 'row',
    gap: 20
  },
  projectGroupImageContainer: {
    width: 108,
    height: 108,
    borderRadius: 12
  },
  projectGroupItemNameHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center'
  },
  projectGroupItemName: (theme: Theme) => ({
    flex: 1,
    fontSize: 18,
    lineHeight: 22,
    fontWeight: '500',
    color: colors[theme].gray[900]
  }),
  projectGroupButton: (theme: Theme) => ({
    flexDirection: 'row',
    gap: 20,
    backgroundColor: colors[theme].background,
    paddingHorizontal: 20
  }),
  projectGroupItemImageContainer: {
    width: 108,
    height: 108,
    borderRadius: 12,
    zIndex: 2
  },
  projectGroupItemLabelsContainer: {
    width: 108,
    flex: 1,
    justifyContent: 'flex-start',
    zIndex: 1,
    gap: 12
  },
  projectGroupItemDetails: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center'
  },
  projectGroupItemLastEdited: (theme: Theme) => ({
    fontSize: 14,
    fontWeight: '500',
    color: colors[theme].gray[400]
  }),
  actionButton: {
    width: 48,
    height: 48,
    borderRadius: 50,
    justifyContent: 'center',
    alignItems: 'center'
  },
  actionButtonsContainer: {
    flexDirection: 'row',
    gap: 12,
    position: 'absolute',
    top: '50%',
    right: 20,
    transform: [{ translateY: '-50%' }],
    alignSelf: 'center'
  }
})
